{"Channel": {"name": "bug-davidgarcia-SummarizeForce", "channelID": "ch-force-9223c9"}, "Message": {"User": {"userId": "eid_f4f58faa", "timestamp": "2027-04-05T21:04:00", "text": "Hi team, I found some interesting open-source bugs that might help us with our current issues. Let's take a look! 😊", "utterranceID": "20270405-0-7d6da"}, "Reactions": []}, "ThreadReplies": [], "id": "20270405-0-7d6da"}
